type LegacyTaskRow = {
  id: string;
  kind: string;
  repo_id: string | null;
  worktree_dir: string;
  status: string;
  created_at: number;
};

/**
 * The status mapping (design section 4.1), applied once at migration:
 * queued -> open (the gate stays as the hold); running/idle/interrupted ->
 * active with that activity; completed -> delivered while its worktree is
 * present, else done/finished; cancelled/failed -> dropped with the reason;
 * a parked decision row -> kind decision, open, still held by its captain
 * gate (the card id stays in gate_ref).
 */
export function mapLegacyStatus(row: { status: string; worktree_dir: string }): {
  status: string;
  activity: string | null;
  closedReason: string | null;
} {
  switch (row.status) {
    case "queued":
      return { status: "open", activity: null, closedReason: null };
    case "running":
    case "idle":
    case "interrupted":
      return { status: "active", activity: row.status, closedReason: null };
    case "completed":
      return row.worktree_dir
        ? { status: "delivered", activity: null, closedReason: "finished" }
        : { status: "done", activity: null, closedReason: "finished" };
    case "cancelled":
      return { status: "dropped", activity: null, closedReason: "cancelled" };

