/**
 * Fill closed_at on already-migrated closed rows. Migration 17 added the
 * column and mapped status but never stamped the close, so delivered work
 * sat with closed_at NULL. Only those three statuses; only nulls; the
 * stamp is the row's own updated_at (falling back to created_at).
 */
export function migrateLegacyClosedAt(db: AppDatabase): void {
  db.exec(`
    UPDATE tasks
    SET closed_at = COALESCE(updated_at, created_at)
    WHERE closed_at IS NULL
      AND status IN ('delivered', 'done', 'dropped')
  `);
}

