/**
 * Fill closed_at on already-migrated closed rows. Migration 17 added the
 * column and mapped status but never stamped the close, so delivered work
 * sat with closed_at NULL. Only those three statuses; only nulls; the
 * stamp is the row's own updated_at (falling back to created_at).
 */
export function migrateLegacyClosedAt(db: AppDatabase): void {
  db.exec(`
    UPDATE tasks
    SET closed_at = COALESCE(updated_at, created_at)
    WHERE closed_at IS NULL
      AND status IN ('delivered', 'done', 'dropped')
  `);
}

function migrateCreatedEvents(db: AppDatabase): void {
  db.exec(`
    INSERT INTO task_events (task_id, at, actor, kind, text, feed)
      SELECT id, created_at, 'host', 'created', 'created "' || title || '"', 0
      FROM tasks ORDER BY created_at, id;
  `);
}

export function openDatabase(userDataDir: string, throughVersion?: number): AppDatabase {
  mkdirSync(userDataDir, { recursive: true });
  const db = new Database(join(userDataDir, "firstmate.db"));
  db.pragma("journal_mode = WAL");
  db.pragma("foreign_keys = ON");
  migrate(db, throughVersion);
  return db;
}

export function openInMemoryDatabase(throughVersion?: number): AppDatabase {
  const db = new Database(":memory:");
  migrate(db, throughVersion);
  return db;
